var TelegramUpdateDialog=function(n){var t={initialize:function(){t.initEvent();t.showDialog()},initEvent:function(){n("#btnUpdateNow").on("click",function(){t.redirectToMyAccount()});n("#btnRemindLater").on("click",function(){t.hideDialog()})},showDialog:function(){const t=sessionStorage.getItem("isShowNotiDialog");t==="1"&&n("#telegramUpdateModal").modal({backdrop:"static",keyboard:!1})},hideDialog:function(){sessionStorage.setItem("isShowNotiDialog","0");n("#telegramUpdateModal").modal("hide")},redirectToMyAccount:function(){t.hideDialog();sessionStorage.setItem("focusTelegram","1");Site.redirect(Site.resolveRelativeUrl("UserPanel/Main/#MyAccount"))}};return t}(jQuery);TelegramUpdateDialog.initialize();